import type { PopoverProps as CorePopoverProps } from "../popover.types";

import React, { createContext, useContext, useEffect, useRef, useState } from "react";
import {
  autoUpdate,
  flip,
  arrow,
  offset as floatingOffset,
  shift,
  useDismiss,
  useFloating,
  useFocus,
  useInteractions,
  useRole,
  useClick,
  useTransitionStyles,
  type Placement,
  type UseFloatingReturn,
} from "@floating-ui/react";
import { isNullish } from "@system";

export interface UsePopoverOptions {
  position?: Placement;
  open?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  offset?: number;
  arrow?: boolean;
  variant?: CorePopoverProps["variant"];
  styleSlots?: CorePopoverProps["styleSlots"];
  dismissable?: boolean;
}

export interface PopoverContextValue {
  arrowRef: React.RefObject<SVGSVGElement>;
  floatingStyles: UseFloatingReturn["floatingStyles"];
  floatingContext: UseFloatingReturn["context"];
  getReferenceProps: ReturnType<typeof useInteractions>["getReferenceProps"];
  getFloatingProps: ReturnType<typeof useInteractions>["getFloatingProps"];
  isMounted: boolean;
  refs: UseFloatingReturn["refs"];
  styles: React.CSSProperties;
  currentOpenState: boolean;
  actualPlacement: Placement;
  showArrow: boolean;
  variant?: CorePopoverProps["variant"];
  styleSlots?: CorePopoverProps["styleSlots"];
}

export const PopoverContext = createContext<PopoverContextValue | null>(null);

export const usePopoverContext = () => {
  const context = useContext(PopoverContext);
  if (!context) {
    throw new Error("usePopoverContext must be used within a PopoverProvider");
  }
  return context;
};

export const usePopover = (options: UsePopoverOptions): PopoverContextValue => {
  const {
    position = "top",
    open: controlledOpen,
    onOpenChange,
    offset,
    arrow: arrowEnabled = true,
    variant = "default",
    styleSlots,
    dismissable,
  } = options;

  const arrowRef = useRef(null);
  const [internalOpen, setInternalOpen] = useState(controlledOpen ?? false);
  const currentOpenState = controlledOpen ?? internalOpen;

  useEffect(() => {
    if (typeof controlledOpen === "boolean") {
      if (controlledOpen !== internalOpen) {
        setInternalOpen(controlledOpen);
        onOpenChange?.(controlledOpen);
      }
    }
  }, [controlledOpen, internalOpen, onOpenChange]);

  const {
    refs,
    floatingStyles,
    context,
    placement: actualPlacement,
  } = useFloating({
    open: currentOpenState,
    onOpenChange: (newOpenState) => {
      if (isNullish(controlledOpen)) {
        setInternalOpen(newOpenState);
      }
      onOpenChange?.(newOpenState);
    },
    placement: position,
    whileElementsMounted: autoUpdate,
    middleware: [
      floatingOffset(offset),
      flip(),
      shift(),
      arrow({
        element: arrowRef,
      }),
    ],
  });

  // Interactions: click to toggle, dismiss to close on outside/Escape
  const click = useClick(context, {
    enabled: isNullish(controlledOpen),
  });
  const dismiss = useDismiss(context, {
    enabled: dismissable,
  });
  const role = useRole(context, { role: "dialog" });

  const interactions: Array<
    | ReturnType<typeof useClick>
    | ReturnType<typeof useFocus>
    | ReturnType<typeof useDismiss>
    | ReturnType<typeof useRole>
  > = [role];

  if (isNullish(controlledOpen)) {
    interactions.push(click);
  }

  if (dismissable) {
    interactions.push(dismiss);
  }

  // Get interaction props and strip aria-expanded for dialog triggers to satisfy a11y
  const { getReferenceProps: baseGetReferenceProps, getFloatingProps } =
    useInteractions(interactions);

  const getReferenceProps: typeof baseGetReferenceProps = (
    ...args: Parameters<typeof baseGetReferenceProps>
  ) => {
    type RefProps = ReturnType<typeof baseGetReferenceProps>;
    const props = baseGetReferenceProps(...args) as RefProps;

    if (props["aria-haspopup"] === "dialog") {
      delete props["aria-expanded"];
    }
    return props;
  };

  const duration = 250;
  const { isMounted, styles } = useTransitionStyles(context, {
    duration,
    initial: {
      opacity: 0,
    },
  });

  return {
    refs,
    floatingStyles,
    floatingContext: context,
    arrowRef,
    getReferenceProps,
    getFloatingProps,
    isMounted,
    styles,
    currentOpenState,
    actualPlacement,
    showArrow: arrowEnabled,
    variant,
    styleSlots,
  };
};
